import json
with open('context/fees.json') as f:
    data = json.load(f)

# Let me look at the matching entries more carefully
# Specifically look at account_type field - it could be a list or single value
for entry in data:
    ac = entry.get('account_type')
    aci = entry.get('aci')

    ac_match = False
    if ac is None:
        ac_match = True
    elif isinstance(ac, list):
        if 'R' in ac:
            ac_match = True
    else:
        if ac == 'R':
            ac_match = True

    aci_match = False
    if aci is None:
        aci_match = True
    elif isinstance(aci, list):
        if 'B' in aci:
            aci_match = True
    else:
        if aci == 'B':
            aci_match = True

    if ac_match and aci_match:
        # Let's check a few sample entries
        if entry['ID'] in [34, 39, 49]:
            print(f'ID={entry[\"ID\"]}: account_type={ac}, aci={aci}')
"

